class NumberContainers {
    private final java.util.Map<Integer, Integer> indexToNumber = new java.util.HashMap<>();
    private final java.util.Map<Integer, java.util.TreeSet<Integer>> numberToIndices = new java.util.HashMap<>();

    public NumberContainers() {
    }

    public void change(int index, int number) {
        Integer oldNumber = indexToNumber.get(index);
        if (oldNumber != null) {
            java.util.TreeSet<Integer> oldSet = numberToIndices.get(oldNumber);
            oldSet.remove(index);
            if (oldSet.isEmpty()) {
                numberToIndices.remove(oldNumber);
            }
        }
        indexToNumber.put(index, number);
        numberToIndices.computeIfAbsent(number, key -> new java.util.TreeSet<>()).add(index);
    }

    public int find(int number) {
        java.util.TreeSet<Integer> indices = numberToIndices.get(number);
        if (indices == null || indices.isEmpty()) {
            return -1;
        }
        return indices.first();
    }
}

class NumberContainers {
    private final java.util.Map<Integer, Integer> indexToNumber = new java.util.HashMap<>();
    private final java.util.Map<Integer, java.util.PriorityQueue<Integer>> numberToHeap = new java.util.HashMap<>();

    public NumberContainers() {
    }

    public void change(int index, int number) {
        indexToNumber.put(index, number);
        numberToHeap.computeIfAbsent(number, key -> new java.util.PriorityQueue<>()).offer(index);
    }

    public int find(int number) {
        java.util.PriorityQueue<Integer> heap = numberToHeap.get(number);
        if (heap == null) {
            return -1;
        }
        while (!heap.isEmpty()) {
            int index = heap.peek();
            if (indexToNumber.getOrDefault(index, -1) == number) {
                return index;
            }
            heap.poll();
        }
        return -1;
    }
}

class NumberContainers {
    private static class Record implements Comparable<Record> {
        final int number;
        final int index;

        Record(int number, int index) {
            this.number = number;
            this.index = index;
        }

        public int compareTo(Record other) {
            if (number != other.number) {
                return Integer.compare(number, other.number);
            }
            return Integer.compare(index, other.index);
        }
    }

    private final java.util.Map<Integer, Integer> indexToNumber = new java.util.HashMap<>();
    private final java.util.TreeSet<Record> records = new java.util.TreeSet<>();

    public NumberContainers() {
    }

    public void change(int index, int number) {
        Integer oldNumber = indexToNumber.put(index, number);
        if (oldNumber != null) {
            records.remove(new Record(oldNumber, index));
        }
        records.add(new Record(number, index));
    }

    public int find(int number) {
        Record candidate = records.ceiling(new Record(number, 0));
        if (candidate == null || candidate.number != number) {
            return -1;
        }
        return candidate.index;
    }
}

class NumberContainers {
    private final java.util.Map<Integer, Integer> indexToNumber = new java.util.HashMap<>();
    private final java.util.Map<Integer, IndexedHeap> numberToHeap = new java.util.HashMap<>();

    public NumberContainers() {
    }

    public void change(int index, int number) {
        Integer oldNumber = indexToNumber.get(index);
        if (oldNumber != null) {
            numberToHeap.get(oldNumber).remove(index);
        }
        indexToNumber.put(index, number);
        numberToHeap.computeIfAbsent(number, key -> new IndexedHeap()).add(index);
    }

    public int find(int number) {
        IndexedHeap heap = numberToHeap.get(number);
        if (heap == null || heap.isEmpty()) {
            return -1;
        }
        return heap.peek();
    }

    private static class IndexedHeap {
        private final java.util.ArrayList<Integer> heap = new java.util.ArrayList<>();
        private final java.util.Map<Integer, Integer> position = new java.util.HashMap<>();

        boolean isEmpty() {
            return heap.isEmpty();
        }

        int peek() {
            return heap.get(0);
        }

        void add(int index) {
            position.put(index, heap.size());
            heap.add(index);
            siftUp(heap.size() - 1);
        }

        void remove(int index) {
            Integer slot = position.remove(index);
            if (slot == null) {
                return;
            }
            int lastValue = heap.remove(heap.size() - 1);
            if (slot < heap.size()) {
                heap.set(slot, lastValue);
                position.put(lastValue, slot);
                siftUp(slot);
                siftDown(position.get(lastValue));
            }
        }

        private void siftUp(int index) {
            while (index > 0) {
                int parent = (index - 1) / 2;
                if (heap.get(parent) <= heap.get(index)) {
                    break;
                }
                swap(parent, index);
                index = parent;
            }
        }

        private void siftDown(int index) {
            while (true) {
                int left = index * 2 + 1;
                int right = left + 1;
                int best = index;
                if (left < heap.size() && heap.get(left) < heap.get(best)) {
                    best = left;
                }
                if (right < heap.size() && heap.get(right) < heap.get(best)) {
                    best = right;
                }
                if (best == index) {
                    break;
                }
                swap(index, best);
                index = best;
            }
        }

        private void swap(int left, int right) {
            int a = heap.get(left);
            int b = heap.get(right);
            heap.set(left, b);
            heap.set(right, a);
            position.put(a, right);
            position.put(b, left);
        }
    }
}

class NumberContainers {
    private static final int INF = Integer.MAX_VALUE;
    private static final int MIN_INDEX = 1;
    private static final int MAX_INDEX = 1_000_000_000;

    private static class Node {
        Node left;
        Node right;
        int min = INF;
    }

    private final java.util.Map<Integer, Integer> indexToNumber = new java.util.HashMap<>();
    private final java.util.Map<Integer, Node> numberToRoot = new java.util.HashMap<>();

    public NumberContainers() {
    }

    public void change(int index, int number) {
        Integer oldNumber = indexToNumber.get(index);
        if (oldNumber != null) {
            update(numberToRoot.get(oldNumber), MIN_INDEX, MAX_INDEX, index, false);
        }
        indexToNumber.put(index, number);
        Node root = numberToRoot.computeIfAbsent(number, key -> new Node());
        update(root, MIN_INDEX, MAX_INDEX, index, true);
    }

    public int find(int number) {
        Node root = numberToRoot.get(number);
        if (root == null || root.min == INF) {
            return -1;
        }
        return root.min;
    }

    private void update(Node node, int left, int right, int index, boolean present) {
        if (left == right) {
            node.min = present ? index : INF;
            return;
        }
        int mid = left + (right - left) / 2;
        if (index <= mid) {
            if (node.left == null) {
                node.left = new Node();
            }
            update(node.left, left, mid, index, present);
        } else {
            if (node.right == null) {
                node.right = new Node();
            }
            update(node.right, mid + 1, right, index, present);
        }
        int leftMin = node.left == null ? INF : node.left.min;
        int rightMin = node.right == null ? INF : node.right.min;
        node.min = Math.min(leftMin, rightMin);
    }
}
